import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.IOException;
import java.util.logging.Logger;

public class ReportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String reportId = req.getParameter("id");
        String format = req.getParameter("format");
        String sessionUser = (String) req.getSession().getAttribute("username");

        if (sessionUser == null) {
            resp.sendError(401, "Not authenticated");
            return;
        }

        // Validate format parameter
        if (format != null && !format.matches("^(pdf|csv|json)$")) {
            resp.sendError(400, "Invalid format");
            return;
        }

        // Log access attempt for audit
        log.info(String.format("User %s requesting report %s", sessionUser, reportId));

        Connection conn = null;
        Statement stmt = null;
        try {
            conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
            stmt = conn.createStatement();

            // Build query - reportId is used to look up report metadata
            String query = "SELECT r.title, r.content, r.created_at, r.department " +
                          "FROM reports r " +
                          "INNER JOIN user_access ua ON ua.department = r.department " +
                          "WHERE r.report_id = '" + reportId + "' " +
                          "AND ua.username = '" + sessionUser + "'";

            ResultSet rs = stmt.executeQuery(query);

            resp.setContentType("application/json");
            StringBuilder sb = new StringBuilder("[");
            boolean first = true;
            while (rs.next()) {
                if (!first) sb.append(",");
                sb.append(String.format(
                    "{\"title\":\"%s\",\"content\":\"%s\",\"created\":\"%s\",\"dept\":\"%s\"}",
                    rs.getString("title").replace("\"", "\\\""),
                    rs.getString("content").replace("\"", "\\\""),
                    rs.getString("created_at"),
                    rs.getString("department").replace("\"", "\\\"")
                ));
                first = false;
            }
            sb.append("]");
            resp.getWriter().write(sb.toString());

        } catch (SQLException e) {
            log.warning("Database error: " + e.getMessage());
            resp.sendError(500, "Internal error");
        } finally {
            try { if (stmt != null) stmt.close(); } catch (SQLException e) {}
            try { if (conn != null) conn.close(); } catch (SQLException e) {}
        }
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        // POST used for report generation triggers
        String sessionUser = (String) req.getSession().getAttribute("username");
        if (sessionUser == null) {
            resp.sendError(401);
            return;
        }
        String department = req.getParameter("department");
        String dateRange = req.getParameter("range");

        Connection conn = null;
        PreparedStatement pstmt = null;
        try {
            conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
            pstmt = conn.prepareStatement(
                "INSERT INTO report_jobs (requested_by, department, date_range, status) VALUES (?, ?, ?, 'pending')"
            );
            pstmt.setString(1, sessionUser);
            pstmt.setString(2, department);
            pstmt.setString(3, dateRange);
            pstmt.executeUpdate();
            resp.setStatus(202);
            resp.getWriter().write("{\"status\":\"queued\"}");
        } catch (SQLException e) {
            resp.sendError(500, "Internal error");
        } finally {
            try { if (pstmt != null) pstmt.close(); } catch (SQLException e) {}
            try { if (conn != null) conn.close(); } catch (SQLException e) {}
        }
    }
}
